    // SCCP.
    struct Sccp {
        // Values of Status: Enable/disable SCCP.
        struct Status {
            static constexpr std::string_view disable = "disable";
            static constexpr std::string_view enable = "enable";
        };

        // Values of BlockMcast: Enable/disable block multicast RTP connections.
        struct BlockMcast {
            static constexpr std::string_view disable = "disable";
            static constexpr std::string_view enable = "enable";
        };

        // Values of VerifyHeader: Enable/disable verify SCCP header content.
        struct VerifyHeader {
            static constexpr std::string_view disable = "disable";
            static constexpr std::string_view enable = "enable";
        };

        // Values of LogCallSummary: Enable/disable log summary of SCCP calls.
        struct LogCallSummary {
            static constexpr std::string_view disable = "disable";
            static constexpr std::string_view enable = "enable";
        };

        // Values of LogViolations: Enable/disable logging of SCCP violations.
        struct LogViolations {
            static constexpr std::string_view disable = "disable";
            static constexpr std::string_view enable = "enable";
        };

        fortiapi::Field<std::string> status;  // Enable/disable SCCP.
        fortiapi::Field<std::string> block_mcast;  // Enable/disable block multicast RTP connections.
        fortiapi::Field<std::string> verify_header;  // Enable/disable verify SCCP header content.
        fortiapi::Field<std::string> log_call_summary;  // Enable/disable log summary of SCCP calls.
        fortiapi::Field<std::string> log_violations;  // Enable/disable logging of SCCP violations.
        fortiapi::Field<std::uint32_t> max_calls;  // Maximum calls per minute per SCCP client (max 65535).

        template<typename Self, typename Visitor>
        static void visit(Self& self, Visitor&& v) {
            v("status", self.status, R"("enable")", fortiapi::none);
            v("block-mcast", self.block_mcast, R"("disable")", fortiapi::none);
            v("verify-header", self.verify_header, R"("disable")", fortiapi::none);
            v("log-call-summary", self.log_call_summary, R"("disable")", fortiapi::none);
            v("log-violations", self.log_violations, R"("disable")", fortiapi::none);
            v("max-calls", self.max_calls, R"(0)", fortiapi::none);
        }
    };

    // MSRP.
    struct Msrp {
        // Values of Status: Enable/disable MSRP.
        struct Status {
            static constexpr std::string_view disable = "disable";
            static constexpr std::string_view enable = "enable";
        };

        // Values of LogViolations: Enable/disable logging of MSRP violations.
        struct LogViolations {
            static constexpr std::string_view disable = "disable";
            static constexpr std::string_view enable = "enable";
        };

        // Values of MaxMsgSizeAction: Action for violation of max-msg-size.
        struct MaxMsgSizeAction {
            static constexpr std::string_view pass = "pass";
            static constexpr std::string_view block = "block";
            static constexpr std::string_view reset = "reset";
            static constexpr std::string_view monitor = "monitor";
        };

        fortiapi::Field<std::string> status;  // Enable/disable MSRP.
        fortiapi::Field<std::string> log_violations;  // Enable/disable logging of MSRP violations.
        fortiapi::Field<std::uint32_t> max_msg_size;  // Maximum allowable MSRP message size (1-65535).
        fortiapi::Field<std::string> max_msg_size_action;  // Action for violation of max-msg-size.

        template<typename Self, typename Visitor>
        static void visit(Self& self, Visitor&& v) {
            v("status", self.status, R"("enable")", fortiapi::none);
            v("log-violations", self.log_violations, R"("enable")", fortiapi::none);
            v("max-msg-size", self.max_msg_size, R"(0)", fortiapi::none);
            v("max-msg-size-action", self.max_msg_size_action, R"("pass")", fortiapi::none);
        }
    };

    fortiapi::Field<std::string> name;  // Profile name. Required.
    fortiapi::Field<std::string> feature_set;  // IPS or voipd (SIP-ALG) inspection feature set.
    fortiapi::Field<std::string> comment;  // Comment.
    fortiapi::Field<Sip> sip;  // SIP.
    fortiapi::Field<Sccp> sccp;  // SCCP.
    fortiapi::Field<Msrp> msrp;  // MSRP.

    template<typename Self, typename Visitor>
    static void visit(Self& self, Visitor&& v) {
        v("name", self.name, R"("")", fortiapi::none);
        v("feature-set", self.feature_set, R"("voipd")", fortiapi::none);
        v("comment", self.comment, R"("")", fortiapi::none);
        v("sip", self.sip, R"({})", fortiapi::none);
        v("sccp", self.sccp, R"({})", fortiapi::none);
        v("msrp", self.msrp, R"({})", fortiapi::none);
    }
